INSERT INTO dictation_sentences (text, translation_fr, difficulty, category) VALUES
-- Réservation
('I would like to book a single room with breakfast for three nights.', 'Je voudrais réserver une chambre simple avec petit-déjeuner pour trois nuits.', 'A2', 'voyage'),
('Do you have any rooms available with a view of the sea?', 'Avez-vous des chambres disponibles avec vue sur la mer ?', 'A2', 'voyage'),
('The reservation is confirmed for the fifteenth of August.', 'La réservation est confirmée pour le quinze août.', 'A2', 'voyage'),
('I need to cancel my booking because my flight has been cancelled.', 'Je dois annuler ma réservation parce que mon vol a été annulé.', 'B1', 'voyage'),
('Is there a discount for booking more than five nights in advance?', 'Y a-t-il une réduction pour une réservation de plus de cinq nuits à l''avance ?', 'B1', 'voyage'),
('The total cost includes taxes and a daily cleaning fee.', 'Le coût total comprend les taxes et des frais de nettoyage quotidiens.', 'B1', 'voyage'),
('Can I pay the deposit with a credit card or do you require cash?', 'Puis-je payer le dépôt avec une carte de crédit ou exigez-vous du liquide ?', 'B1', 'voyage'),
('Your booking reference number is seven eight nine four five.', 'Votre numéro de référence de réservation est sept huit neuf quatre cinq.', 'A2', 'voyage'),
